set_xlabel('Series 1')\n    combined_ax.set_ylabel('Series 2')\n    combined_ax.set_title('Combined K-Means Cluster Visualization')\n    combined_ax.legend(loc='best')\n    return combined_fig, individual_figs\n\n# test\nrng = np.random.RandomState(0)\npairs = [(pd.Series(rng.normal(0,1,50)), pd.Series(rng.normal(0,1,50))),\n         (pd.Series(rng.normal(5,1,50)), pd.Series(rng.normal(5,1,50)))]\ncf, fs = combined_visualization(pairs, 3)\nprint(type(cf), len(fs))\nprint(cf.axes[0].get_legend_handles_labels()[1])\nprint([f.axes[0].get_legend_handles_labels()[1] for f in fs])\nplt.close('all')\n"
